1	/**
2	 * @fileoverview Plugin UI static file serving route
3	 *
4	 * Serves plugin UI bundles from the plugin's dist/ui/ directory under the
5	 * `/_plugins/:pluginId/ui/*` namespace. This is specified in PLUGIN_SPEC.md
6	 * §19.0.3 (Bundle Serving).
7	 *
8	 * Plugin UI bundles are pre-built ESM that the host serves as static assets.
9	 * The host dynamically imports the plugin's UI entry module from this path,
10	 * resolves the named export declared in `ui.slots[].exportName`, and mounts
11	 * it into the extension slot.
12	 *
13	 * Security:
14	 * - Path traversal is prevented by resolving the requested path and verifying
15	 *   it stays within the plugin's UI directory.
16	 * - Only plugins in 'ready' status have their UI served.
17	 * - Only plugins that declare `entrypoints.ui` serve UI bundles.
18	 *
19	 * Cache Headers:
20	 * - Files with content-hash patterns in their name (e.g., `index-a1b2c3d4.js`)
21	 *   receive `Cache-Control: public, max-age=31536000, immutable`.
22	 * - Other files receive `Cache-Control: public, max-age=0, must-revalidate`
23	 *   with ETag-based conditional request support.
24	 *
25	 * @module server/routes/plugin-ui-static
26	 * @see doc/plugins/PLUGIN_SPEC.md §19.0.3 — Bundle Serving
27	 * @see doc/plugins/PLUGIN_SPEC.md §25.4.5 — Frontend Cache Invalidation
28	 */
29	
30	import { Router } from "express";
31	import path from "node:path";
32	import fs from "node:fs";
33	import crypto from "node:crypto";
34	import type { Db } from "@paperclipai/db";
35	import { pluginRegistryService } from "../services/plugin-registry.js";
36	import { logger } from "../middleware/logger.js";
37	
38	// ---------------------------------------------------------------------------
39	// Constants
40	// ---------------------------------------------------------------------------
41	
42	/**
43	 * Regex to detect content-hashed filenames.
44	 *
45	 * Matches patterns like:
46	 * - `index-a1b2c3d4.js`
47	 * - `styles.abc123def.css`
48	 * - `chunk-ABCDEF01.mjs`
49	 *
50	 * The hash portion must be at least 8 hex characters to avoid false positives.
51	 */
52	const CONTENT_HASH_PATTERN = /[.-][a-fA-F0-9]{8,}\.\w+$/;
53	
54	/**
55	 * Cache-Control header for content-hashed files.
56	 * These files are immutable by definition (the hash changes when content changes).
57	 */
58	/** 1 year in seconds — standard for content-hashed immutable resources. */
59	const ONE_YEAR_SECONDS = 365 * 24 * 60 * 60; // 31_536_000
60	const CACHE_CONTROL_IMMUTABLE = `public, max-age=${ONE_YEAR_SECONDS}, immutable`;
61	
62	/**
63	 * Cache-Control header for non-hashed files.
64	 * These files must be revalidated on each request (ETag-based).
65	 */
66	const CACHE_CONTROL_REVALIDATE = "public, max-age=0, must-revalidate";
67	
68	/**
69	 * MIME types for common plugin UI bundle file extensions.
70	 */
71	const MIME_TYPES: Record<string, string> = {
72	  ".js": "application/javascript; charset=utf-8",
73	  ".mjs": "application/javascript; charset=utf-8",
74	  ".css": "text/css; charset=utf-8",
75	  ".json": "application/json; charset=utf-8",
76	  ".map": "application/json; charset=utf-8",
77	  ".html": "text/html; charset=utf-8",
78	  ".svg": "image/svg+xml",
79	  ".png": "image/png",
80	  ".jpg": "image/jpeg",
81	  ".jpeg": "image/jpeg",
82	  ".gif": "image/gif",
83	  ".webp": "image/webp",
84	  ".woff": "font/woff",
85	  ".woff2": "font/woff2",
86	  ".ttf": "font/ttf",
87	  ".eot": "application/vnd.ms-fontobject",
88	  ".ico": "image/x-icon",
89	  ".txt": "text/plain; charset=utf-8",
90	};
91	
92	// ---------------------------------------------------------------------------
93	// Helper
94	// ---------------------------------------------------------------------------
95	
96	/**
97	 * Resolve a plugin's UI directory from its package location.
98	 *
99	 * The plugin's `packageName` is stored in the DB. We resolve the package path
100	 * from the local plugin directory (DEFAULT_LOCAL_PLUGIN_DIR) by looking in
101	 * `node_modules`. If the plugin was installed from a local path, the manifest
102	 * `entrypoints.ui` path is resolved relative to the package directory.
103	 *
104	 * @param localPluginDir - The plugin installation directory
105	 * @param packageName - The npm package name
106	 * @param entrypointsUi - The UI entrypoint path from the manifest (e.g., "./dist/ui/")
107	 * @returns Absolute path to the UI directory, or null if not found
108	 */
109	export function resolvePluginUiDir(
110	  localPluginDir: string,
111	  packageName: string,
112	  entrypointsUi: string,
113	  packagePath?: string | null,
114	): string | null {
115	  // For local-path installs, prefer the persisted package path.
116	  if (packagePath) {
117	    const resolvedPackagePath = path.resolve(packagePath);
118	    if (fs.existsSync(resolvedPackagePath)) {
119	      const uiDirFromPackagePath = path.resolve(resolvedPackagePath, entrypointsUi);
120	      if (
121	        uiDirFromPackagePath.startsWith(resolvedPackagePath)
122	        && fs.existsSync(uiDirFromPackagePath)
123	      ) {
124	        return uiDirFromPackagePath;
125	      }
126	    }
127	  }
128	
129	  // Resolve the package root within the local plugin directory's node_modules.
130	  // npm installs go to <localPluginDir>/node_modules/<packageName>/
131	  let packageRoot: string;
132	  if (packageName.startsWith("@")) {
133	    // Scoped package: @scope/name -> node_modules/@scope/name
134	    packageRoot = path.join(localPluginDir, "node_modules", ...packageName.split("/"));
135	  } else {
136	    packageRoot = path.join(localPluginDir, "node_modules", packageName);
137	  }
138	
139	  // If the standard location doesn't exist, the plugin may have been installed
140	  // from a local path. Try to check if the package.json is accessible at the
141	  // computed path or if the package is found elsewhere.
142	  if (!fs.existsSync(packageRoot)) {
143	    // For local-path installs, the packageName may be a directory that doesn't
144	    // live inside node_modules. Check if the package exists directly at the
145	    // localPluginDir level.
146	    const directPath = path.join(localPluginDir, packageName);
147	    if (fs.existsSync(directPath)) {
148	      packageRoot = directPath;
149	    } else {
150	      return null;
151	    }
152	  }
153	
154	  // Resolve the UI directory relative to the package root
155	  const uiDir = path.resolve(packageRoot, entrypointsUi);
156	
157	  // Verify the resolved UI directory exists and is actually inside the package
158	  if (!fs.existsSync(uiDir)) {
159	    return null;
160	  }
161	
162	  return uiDir;
163	}
164	
165	/**
166	 * Compute an ETag from file stat (size + mtime).
167	 * This is a lightweight approach that avoids reading the file content.
168	 */
169	function computeETag(size: number, mtimeMs: number): string {
170	  const ETAG_VERSION = "v2";
171	  const hash = crypto
172	    .createHash("md5")
173	    .update(`${ETAG_VERSION}:${size}-${mtimeMs}`)
174	    .digest("hex")
175	    .slice(0, 16);
176	  return `"${hash}"`;
177	}
178	
179	// ---------------------------------------------------------------------------
180	// Route factory
181	// ---------------------------------------------------------------------------
182	
183	/**
184	 * Options for the plugin UI static route.
185	 */
186	export interface PluginUiStaticRouteOptions {
187	  /**
188	   * The local plugin installation directory.
189	   * This is where plugins are installed via `npm install --prefix`.
190	   * Defaults to the standard `~/.paperclip/plugins/` location.
191	   */
192	  localPluginDir: string;
193	}
194	
195	/**
196	 * Create an Express router that serves plugin UI static files.
197	 *
198	 * This route handles `GET /_plugins/:pluginId/ui/*` requests by:
199	 * 1. Looking up the plugin in the registry by ID or key
200	 * 2. Verifying the plugin is in 'ready' status with UI declared
201	 * 3. Resolving the file path within the plugin's dist/ui/ directory
202	 * 4. Serving the file with appropriate cache headers
203	 *
204	 * @param db - Database connection for plugin registry lookups
205	 * @param options - Configuration options
206	 * @returns Express router
207	 */
208	export function pluginUiStaticRoutes(db: Db, options: PluginUiStaticRouteOptions) {
209	  const router = Router();
210	  const registry = pluginRegistryService(db);
211	  const log = logger.child({ service: "plugin-ui-static" });
212	
213	  /**
214	   * GET /_plugins/:pluginId/ui/*
215	   *
216	   * Serve a static file from a plugin's UI bundle directory.
217	   *
218	   * The :pluginId parameter accepts either:
219	   * - Database UUID
220	   * - Plugin key (e.g., "acme.linear")
221	   *
222	   * The wildcard captures the relative file path within the UI directory.
223	   *
224	   * Cache strategy:
225	   * - Content-hashed filenames → immutable, 1-year max-age
226	   * - Other files → must-revalidate with ETag
227	   */
228	  router.get("/_plugins/:pluginId/ui/*filePath", async (req, res) => {
229	    const { pluginId } = req.params;
230	
231	    // Extract the relative file path from the named wildcard.
232	    // In Express 5 with path-to-regexp v8, named wildcards may return
233	    // an array of path segments or a single string.
234	    const rawParam = req.params.filePath;
235	    const rawFilePath = Array.isArray(rawParam)
236	      ? rawParam.join("/")
237	      : rawParam as string | undefined;
238	
239	    if (!rawFilePath || rawFilePath.length === 0) {
240	      res.status(400).json({ error: "File path is required" });
241	      return;
242	    }
243	
244	    // Step 1: Look up the plugin
245	    let plugin = null;
246	    try {
247	      plugin = await registry.getById(pluginId);
248	    } catch (error) {
249	      const maybeCode =
250	        typeof error === "object" && error !== null && "code" in error
251	          ? (error as { code?: unknown }).code
252	          : undefined;
253	      if (maybeCode !== "22P02") {
254	        throw error;
255	      }
256	    }
257	    if (!plugin) {
258	      plugin = await registry.getByKey(pluginId);
259	    }
260	
261	    if (!plugin) {
262	      res.status(404).json({ error: "Plugin not found" });
263	      return;
264	    }
265	
266	    // Step 2: Verify the plugin is ready and has UI declared
267	    if (plugin.status !== "ready") {
268	      res.status(403).json({
269	        error: `Plugin UI is not available (status: ${plugin.status})`,
270	      });
271	      return;
272	    }
273	
274	    const manifest = plugin.manifestJson;
275	    if (!manifest?.entrypoints?.ui) {
276	      res.status(404).json({ error: "Plugin does not declare a UI bundle" });
277	      return;
278	    }
279	
280	    // Step 2b: Check for devUiUrl in plugin config — proxy to local dev server
281	    // when a plugin author has configured a dev server URL for hot-reload.
282	    // See PLUGIN_SPEC.md §27.2 — Local Development Workflow
283	    try {
284	      const configRow = await registry.getConfig(plugin.id);
285	      const devUiUrl =
286	        configRow &&
287	        typeof configRow === "object" &&
288	        "configJson" in configRow &&
289	        (configRow as { configJson: Record<string, unknown> }).configJson?.devUiUrl;
290	
291	      if (typeof devUiUrl === "string" && devUiUrl.length > 0) {
292	        // Dev proxy is only available in development mode
293	        if (process.env.NODE_ENV === "production") {
294	          log.warn(
295	            { pluginId: plugin.id },
296	            "plugin-ui-static: devUiUrl ignored in production",
297	          );
298	          // Fall through to static file serving below
299	        } else {
300	          // Guard against rawFilePath overriding the base URL via protocol
301	          // scheme (e.g. "https://evil.com/x") or protocol-relative paths
302	          // (e.g. "//evil.com/x") which cause `new URL(path, base)` to
303	          // ignore the base entirely.
304	          // Normalize percent-encoding so encoded slashes (%2F) can't bypass
305	          // the protocol/path checks below.
306	          let decodedPath: string;
307	          try {
308	            decodedPath = decodeURIComponent(rawFilePath);
309	          } catch {
310	            res.status(400).json({ error: "Invalid file path" });
311	            return;
312	          }
313	          if (
314	            decodedPath.includes("://") ||
315	            decodedPath.startsWith("//") ||
316	            decodedPath.startsWith("\\\\")
317	          ) {
318	            res.status(400).json({ error: "Invalid file path" });
319	            return;
320	          }
321	
322	          // Proxy the request to the dev server
323	          const targetUrl = new URL(rawFilePath, devUiUrl.endsWith("/") ? devUiUrl : devUiUrl + "/");
324	
325	          // SSRF protection: only allow http/https and localhost targets for dev proxy
326	          if (targetUrl.protocol !== "http:" && targetUrl.protocol !== "https:") {
327	            res.status(400).json({ error: "devUiUrl must use http or https protocol" });
328	            return;
329	          }
330	
331	          // Dev proxy is restricted to loopback addresses only.
332	          // Validate the *constructed* targetUrl hostname (not the base) to
333	          // catch any path-based override that slipped past the checks above.
334	          const devHost = targetUrl.hostname;
335	          const isLoopback =
336	            devHost === "localhost" ||
337	            devHost === "127.0.0.1" ||
338	            devHost === "::1" ||
339	            devHost === "[::1]";
340	          if (!isLoopback) {
341	            log.warn(
342	              { pluginId: plugin.id, devUiUrl, host: devHost },
343	              "plugin-ui-static: devUiUrl must target localhost, rejecting proxy",
344	            );
345	            res.status(400).json({ error: "devUiUrl must target localhost" });
346	            return;
347	          }
348	
349	          log.debug(
350	            { pluginId: plugin.id, devUiUrl, targetUrl: targetUrl.href },
351	            "plugin-ui-static: proxying to devUiUrl",
352	          );
353	
354	          try {
355	            const controller = new AbortController();
356	            const timeout = setTimeout(() => controller.abort(), 10_000);
357	            try {
358	              const upstream = await fetch(targetUrl.href, { signal: controller.signal });
359	              if (!upstream.ok) {
360	                res.status(upstream.status).json({
361	                  error: `Dev server returned ${upstream.status}`,
362	                });
363	                return;
364	              }
365	
366	              const contentType = upstream.headers.get("content-type");
367	              if (contentType) res.set("Content-Type", contentType);
368	              res.set("Cache-Control", "no-cache, no-store, must-revalidate");
369	
370	              const body = await upstream.arrayBuffer();
371	              res.send(Buffer.from(body));
372	              return;
373	            } finally {
374	              clearTimeout(timeout);
375	            }
376	          } catch (proxyErr) {
377	            log.warn(
378	              {
379	                pluginId: plugin.id,
380	                devUiUrl,
381	                err: proxyErr instanceof Error ? proxyErr.message : String(proxyErr),
382	              },
383	              "plugin-ui-static: failed to proxy to devUiUrl, falling back to static",
384	            );
385	            // Fall through to static serving below
386	          }
387	        }
388	      }
389	    } catch {
390	      // Config lookup failure is non-fatal — fall through to static serving
391	    }
392	
393	    // Step 3: Resolve the plugin's UI directory
394	    const uiDir = resolvePluginUiDir(
395	      options.localPluginDir,
396	      plugin.packageName,
397	      manifest.entrypoints.ui,
398	      plugin.packagePath,
399	    );
400	
401	    if (!uiDir) {
402	      log.warn(
403	        { pluginId: plugin.id, pluginKey: plugin.pluginKey, packageName: plugin.packageName },
404	        "plugin-ui-static: UI directory not found on disk",
405	      );
406	      res.status(404).json({ error: "Plugin UI directory not found" });
407	      return;
408	    }
409	
410	    // Step 4: Resolve the requested file path and prevent traversal (including symlinks)
411	    const resolvedFilePath = path.resolve(uiDir, rawFilePath);
412	
413	    // Step 5: Check that the file exists and is a regular file
414	    let fileStat: fs.Stats;
415	    try {
416	      fileStat = fs.statSync(resolvedFilePath);
417	    } catch {
418	      res.status(404).json({ error: "File not found" });
419	      return;
420	    }
421	
422	    // Security: resolve symlinks via realpathSync and verify containment.
423	    // This prevents symlink-based traversal that string-based startsWith misses.
424	    let realFilePath: string;
425	    let realUiDir: string;
426	    try {
427	      realFilePath = fs.realpathSync(resolvedFilePath);
428	      realUiDir = fs.realpathSync(uiDir);
429	    } catch {
430	      res.status(404).json({ error: "File not found" });
431	      return;
432	    }
433	
434	    const relative = path.relative(realUiDir, realFilePath);
435	    if (relative.startsWith("..") || path.isAbsolute(relative)) {
436	      res.status(403).json({ error: "Access denied" });
437	      return;
438	    }
439	
440	    if (!fileStat.isFile()) {
441	      res.status(404).json({ error: "File not found" });
442	      return;
443	    }
444	
445	    // Step 6: Determine cache strategy based on filename
446	    const basename = path.basename(resolvedFilePath);
447	    const isContentHashed = CONTENT_HASH_PATTERN.test(basename);
448	
449	    // Step 7: Set cache headers
450	    if (isContentHashed) {
451	      res.set("Cache-Control", CACHE_CONTROL_IMMUTABLE);
452	    } else {
453	      res.set("Cache-Control", CACHE_CONTROL_REVALIDATE);
454	
455	      // Compute and set ETag for conditional request support
456	      const etag = computeETag(fileStat.size, fileStat.mtimeMs);
457	      res.set("ETag", etag);
458	
459	      // Check If-None-Match for 304 Not Modified
460	      const ifNoneMatch = req.headers["if-none-match"];
461	      if (ifNoneMatch === etag) {
462	        res.status(304).end();
463	        return;
464	      }
465	    }
466	
467	    // Step 8: Set Content-Type
468	    const ext = path.extname(resolvedFilePath).toLowerCase();
469	    const contentType = MIME_TYPES[ext];
470	    if (contentType) {
471	      res.set("Content-Type", contentType);
472	    }
473	
474	    // Step 9: Set CORS headers (plugin UI may be loaded from different origin in dev)
475	    res.set("Access-Control-Allow-Origin", "*");
476	
477	    // Step 10: Send the file
478	    // The plugin source can live in Git worktrees (e.g. ".worktrees/...").
479	    // `send` defaults to dotfiles:"ignore", which treats dot-directories as
480	    // not found. We already enforce traversal safety above, so allow dot paths.
481	    res.sendFile(resolvedFilePath, { dotfiles: "allow" }, (err) => {
482	      if (err) {
483	        log.error(
484	          { err, pluginId: plugin.id, filePath: resolvedFilePath },
485	          "plugin-ui-static: error sending file",
486	        );
487	        // Only send error if headers haven't been sent yet
488	        if (!res.headersSent) {
489	          res.status(500).json({ error: "Failed to serve file" });
490	        }
491	      }
492	    });
493	  });
494	
495	  return router;
496	}
